import{_ as c,o as i,c as t,a6 as o}from"./chunks/framework.BIQm0xy3.js";const e="/oop-cpp/assets/E0_chon_cong_cu.BvhXGj95.png",h="/oop-cpp/assets/E1_devcpp_tai.BvBA7A5O.png",a="/oop-cpp/assets/E1_devcpp_project.BT8clwRn.png",l="/oop-cpp/assets/W1_devcpp_that.DgopaLA8.png",d="/oop-cpp/assets/E2_codeblocks.Dw2wADd6.png",r="/oop-cpp/assets/E3_vs_installer.DZX5muCn.png",g="/oop-cpp/assets/E3_vs_solution.ChpOl-Od.png",s="/oop-cpp/assets/E4_clion.B3bfGQN3.png",p="/oop-cpp/assets/E5_vscode.IUyb6OLT.png",u="/oop-cpp/assets/W5_vscode_that.C3Hjrrfv.png",m="/oop-cpp/assets/E6_path.CVqRSDHw.png",b="/oop-cpp/assets/E7_thu_muc.Bw9ATpj1.png",E=JSON.parse('{"title":"Phụ lục E. Cài đặt công cụ: hướng dẫn từng chương trình","description":"","frontmatter":{"title":"Phụ lục E. Cài đặt công cụ: hướng dẫn từng chương trình"},"headers":[],"relativePath":"phu-luc-e.md","filePath":"phu-luc-e.md"}'),v={name:"phu-luc-e.md"};function k(C,n,y,f,B,x){return i(),t("div",null,[...n[0]||(n[0]=[o('<p class="eyebrow">Phụ lục E</p><h1 id="cai-đat-cong-cu-huong-dan-tung-chuong-trinh" tabindex="-1">Cài đặt công cụ: hướng dẫn từng chương trình <a class="header-anchor" href="#cai-đat-cong-cu-huong-dan-tung-chuong-trinh" aria-label="Permalink to &quot;Cài đặt công cụ: hướng dẫn từng chương trình&quot;">​</a></h1><div class="hop ghi-chu"><p class="hop-tieu-de">Đọc dòng này trước, nó tiết kiệm cho bạn cả buổi</p><p><strong>Bạn KHÔNG bắt buộc phải cài g++ riêng.</strong> Dev-C++, Code::Blocks, Visual Studio và CLion đều <strong>kèm sẵn bộ biên dịch</strong> trong bộ cài — tải về, bấm Next mấy lần, là dịch được ngay.</p><p>Chỉ có <strong>một</strong> trường hợp phải cài thêm: bạn chọn <strong>VS Code</strong> hoặc một trình soạn thảo thường (Notepad++, Sublime…). VS Code không phải IDE — nó chỉ là ô để gõ chữ, bên trong không có bộ biên dịch nào. Khi đó xem <a href="./phu-luc-e.html#e-5-vs-code-chi-muc-nay-moi-can-cai-g">mục E.5</a>.</p></div><p>Chọn <strong>một</strong> công cụ rồi làm theo đúng mục của nó. Đừng cài hai ba thứ cùng lúc — mỗi cái đặt compiler ở một chỗ khác nhau và bạn sẽ không biết mình đang dùng cái nào.</p><div class="hop chu-y"><p class="hop-tieu-de">Về các hình trong phụ lục này</p><p>Các hình dưới đây là <strong>hình vẽ minh họa</strong> — sơ đồ mô phỏng giao diện, chỉ đúng từng chỗ bấm. Có thêm <strong>hai ảnh chụp thật</strong>: Dev-C++ (Ảnh E.3a, lấy từ Wikimedia Commons, giấy phép tự do) và VS Code (Ảnh E.8a, giáo trình tự chụp).</p><p>Các công cụ khác không có ảnh chụp thật dùng được: Visual Studio và CLion là phần mềm độc quyền nên không có ảnh tự do; ảnh Code::Blocks trên Commons thực chất là ảnh của trang Softpedia bị đăng lại trái phép; ảnh VS Code tự do trên Commons lại là project JavaScript giao diện tiếng Tây Ban Nha, nên giáo trình tự chụp Ảnh E.8a thay thế. Code::Blocks, Visual Studio và CLion chỉ dùng hình vẽ.</p><p>Bố cục menu và vị trí các nút trong hình vẽ đúng như phần mềm thật ở thời điểm soạn sách, nhưng màu sắc và chi tiết nhỏ có thể khác đôi chút tùy phiên bản.</p><p>Điều cần lấy từ mỗi hình là <strong>đường dẫn menu và thứ tự các bước</strong> — phần đó thì các phiên bản đều giống nhau.</p></div><h2 id="e-0-chon-cong-cu-nao" tabindex="-1">E.0 Chọn công cụ nào <a class="header-anchor" href="#e-0-chon-cong-cu-nao" aria-label="Permalink to &quot;E.0 Chọn công cụ nào&quot;">​</a></h2><figure class="hinh"><img src="'+e+'" alt="Hình E.1 — Năm công cụ thường dùng. Bốn cái đầu kèm sẵn bộ biên dịch." width="600" loading="lazy"><figcaption>Hình E.1 — Năm công cụ thường dùng. Bốn cái đầu kèm sẵn bộ biên dịch.</figcaption></figure><table tabindex="0"><thead><tr><th>Công cụ</th><th>Dung lượng</th><th>Nên chọn khi</th><th style="text-align:center;">Mục</th></tr></thead><tbody><tr><td>Dev-C++</td><td>~60 MB</td><td>Máy yếu, mạng chậm, mới học. Nhẹ và đơn giản nhất.</td><td style="text-align:center;">E.1</td></tr><tr><td>Code::Blocks</td><td>~150 MB</td><td>Muốn nhẹ nhưng giao diện hiện đại hơn Dev-C++.</td><td style="text-align:center;">E.2</td></tr><tr><td>Visual Studio</td><td>~8 GB</td><td>Máy khỏe, ổ đĩa rộng. Trình gỡ lỗi tốt nhất.</td><td style="text-align:center;">E.3</td></tr><tr><td>CLion</td><td>~1 GB</td><td>Đã quen JetBrains. Cần đăng ký license sinh viên.</td><td style="text-align:center;">E.4</td></tr><tr><td>VS Code</td><td>~120 MB</td><td>Đã dùng VS Code cho môn khác. Phải cài thêm compiler.</td><td style="text-align:center;">E.5</td></tr><tr><td>OnlineGDB</td><td>Không cài</td><td>Chưa kịp cài, hoặc đang dùng máy mượn. Chỉ dùng tạm: phòng thi không có mạng.</td><td style="text-align:center;">E.7</td></tr></tbody></table><div class="hop ghi-chu"><p class="hop-tieu-de">Nếu không biết chọn gì</p><p>Chọn <strong>Dev-C++</strong> (<a href="./phu-luc-e.html#e-1-dev-c-khuyen-dung-cho-nguoi-moi">mục E.1</a>). Nó nhẹ nhất, cài nhanh nhất, và làm được đúng mọi thứ môn này cần: nhiều file <code>.h</code> / <code>.cpp</code> trong một project, bấm một nút để dịch và chạy.</p><p>Giao diện nó cũ, nhưng bài thi không chấm giao diện.</p></div><h2 id="e-1-dev-c-khuyen-dung-cho-nguoi-moi" tabindex="-1">E.1 Dev-C++ (khuyên dùng cho người mới) <a class="header-anchor" href="#e-1-dev-c-khuyen-dung-cho-nguoi-moi" aria-label="Permalink to &quot;E.1 Dev-C++ (khuyên dùng cho người mới)&quot;">​</a></h2><h3 id="tai-va-cai" tabindex="-1">Tải và cài <a class="header-anchor" href="#tai-va-cai" aria-label="Permalink to &quot;Tải và cài&quot;">​</a></h3><figure class="hinh"><img src="'+h+'" alt="Hình E.2 — Trang tải trên SourceForge. Chọn đúng bản Embarcadero 6.x." width="600" loading="lazy"><figcaption>Hình E.2 — Trang tải trên SourceForge. Chọn đúng bản Embarcadero 6.x.</figcaption></figure><h3 id="buoc-1-tai-bo-cai" tabindex="-1">Bước 1. Tải bộ cài <a class="header-anchor" href="#buoc-1-tai-bo-cai" aria-label="Permalink to &quot;Bước 1. Tải bộ cài&quot;">​</a></h3><ol><li>Vào <code>sourceforge.net/projects/embarcadero-devcpp</code> rồi bấm nút Download.</li><li>Nếu trang cho chọn file, lấy dòng có dạng <code>Embarcadero_Dev-Cpp_6.x_TDM-GCC_..._Setup.exe</code>.</li><li>Đừng lấy bản <code>Dev-Cpp_5.11</code> — nó từ năm 2015, bộ biên dịch bên trong quá cũ, không dịch được cú pháp C++17 mà môn này dùng.</li></ol><h3 id="buoc-2-cai" tabindex="-1">Bước 2. Cài <a class="header-anchor" href="#buoc-2-cai" aria-label="Permalink to &quot;Bước 2. Cài&quot;">​</a></h3><p>Chạy file vừa tải, bấm Next / I Agree / Install liên tục. <strong>Không cần đổi gì</strong>. Lần đầu mở, nó hỏi ngôn ngữ và theme — chọn gì cũng được.</p><div class="hop ghi-chu"><p class="hop-tieu-de">Không cần làm gì thêm</p><p>Cài xong là dịch được ngay. Không phải cài g++, không phải sửa PATH, không phải mở cửa sổ đen nào. Bộ biên dịch TDM-GCC nằm sẵn trong thư mục Dev-C++.</p></div><h3 id="tao-project-nhieu-file-va-chay" tabindex="-1">Tạo project nhiều file và chạy <a class="header-anchor" href="#tao-project-nhieu-file-va-chay" aria-label="Permalink to &quot;Tạo project nhiều file và chạy&quot;">​</a></h3><figure class="hinh"><img src="'+a+'" alt="Hình E.3 — Cửa sổ Dev-C++ với một project gồm nhiều file .h và .cpp." width="600" loading="lazy"><figcaption>Hình E.3 — Cửa sổ Dev-C++ với một project gồm nhiều file .h và .cpp.</figcaption></figure><figure class="hinh"><img src="'+l+'" alt="Ảnh thật E.3a — Dev-C++ bản cũ 4.9.9.2. Bản 6.3 trông hiện đại hơn nhưng cùng bố cục: khung Project bên trái, code ở giữa, tab Compile Log phía dưới. Ảnh: Francesco Betti Sorbelli, GPL v2+, qua Wikimedia Commons." width="600" loading="lazy"><figcaption>Ảnh thật E.3a — Dev-C++ bản cũ 4.9.9.2. Bản 6.3 trông hiện đại hơn nhưng cùng bố cục: khung Project bên trái, code ở giữa, tab Compile Log phía dưới. Ảnh: Francesco Betti Sorbelli, GPL v2+, qua Wikimedia Commons.</figcaption></figure><h3 id="buoc-3-tao-project-moi" tabindex="-1">Bước 3. Tạo project mới <a class="header-anchor" href="#buoc-3-tao-project-moi" aria-label="Permalink to &quot;Bước 3. Tạo project mới&quot;">​</a></h3><ol><li><code>File → New → Project…</code></li><li>Chọn <strong>Console Application</strong>, tích <strong>C++ Project</strong> (không phải C Project).</li><li>Đặt tên, ví dụ <code>ThuVien</code>, bấm OK.</li><li>Nó hỏi chỗ lưu — chọn thư mục bài làm của bạn, ví dụ <code>C:\\OOP\\23130007_w05</code>.</li><li>Nó tự tạo sẵn một <code>main.cpp</code>. Xoá hết nội dung mẫu trong đó rồi tự gõ lại.</li></ol><h3 id="buoc-4-them-file-h-va-cpp" tabindex="-1">Bước 4. Thêm file .h và .cpp <a class="header-anchor" href="#buoc-4-them-file-h-va-cpp" aria-label="Permalink to &quot;Bước 4. Thêm file .h và .cpp&quot;">​</a></h3><ol><li><code>File → New → Source File</code> → nó hỏi “Add to project?” → bấm <strong>Yes</strong>.</li><li>Lưu ngay bằng <code>Ctrl+S</code> và đặt <strong>đúng tên đề yêu cầu</strong>, ví dụ <code>Document.h</code> — nhớ gõ cả phần đuôi <code>.h</code>.</li><li>Lặp lại cho từng file. Sau mỗi lần, tên file mới phải hiện ra ở khung <strong>Project</strong> bên trái (số ② trên hình).</li></ol><div class="hop chu-y"><p class="hop-tieu-de">Lỗi số một của Dev-C++</p><p>Nếu bạn tạo file mà chọn <strong>No</strong> ở câu hỏi “Add to project?”, file đó <strong>không thuộc project</strong> và sẽ không được dịch. Bạn sẽ nhận lỗi <code>undefined reference</code> mà không hiểu vì sao — trong khi file rõ ràng đang mở trước mắt.</p><p>Cách sửa: <code>Project → Add to project…</code> rồi chọn file đó. Cách kiểm tra: mọi file phải có tên trong khung Project bên trái.</p></div><h3 id="buoc-5-dich-va-chay" tabindex="-1">Bước 5. Dịch và chạy <a class="header-anchor" href="#buoc-5-dich-va-chay" aria-label="Permalink to &quot;Bước 5. Dịch và chạy&quot;">​</a></h3><ol><li><code>Execute → Compile &amp; Run</code> hoặc bấm <strong>F11</strong>.</li><li>Nhìn khung <strong>Compiler log</strong> phía dưới: dòng <code>Errors</code> phải bằng <code>0</code>.</li><li>Cửa sổ đen hiện ra và in kết quả. Nếu nó đóng ngay, thêm <code>system(&quot;pause&quot;);</code> trước <code>return 0;</code> — hoặc chạy bằng <code>F11</code> chứ đừng bấm đúp file <code>.exe</code>.</li></ol><h3 id="buoc-6-bat-c-17" tabindex="-1">Bước 6. Bật C++17 <a class="header-anchor" href="#buoc-6-bat-c-17" aria-label="Permalink to &quot;Bước 6. Bật C++17&quot;">​</a></h3><p>Chỉ cần làm một lần: <code>Tools → Compiler Options → Settings → Code Generation</code>, ô <strong>Language standard (-std)</strong> chọn <code>ISO C++17</code>. Nếu không thấy mục này, mở <code>Tools → Compiler Options</code> tab <strong>General</strong> rồi thêm <code>-std=c++17</code> vào ô lệnh biên dịch.</p><h2 id="e-2-code-blocks" tabindex="-1">E.2 Code::Blocks <a class="header-anchor" href="#e-2-code-blocks" aria-label="Permalink to &quot;E.2 Code::Blocks&quot;">​</a></h2><figure class="hinh"><img src="'+d+'" alt="Hình E.4 — Trang tải Code::Blocks. Chỉ bản có chữ mingw mới kèm bộ biên dịch." width="600" loading="lazy"><figcaption>Hình E.4 — Trang tải Code::Blocks. Chỉ bản có chữ mingw mới kèm bộ biên dịch.</figcaption></figure><h3 id="buoc-1-tai-đung-file-—-đay-la-cho-hay-sai-nhat" tabindex="-1">Bước 1. Tải đúng file — đây là chỗ hay sai nhất <a class="header-anchor" href="#buoc-1-tai-đung-file-—-đay-la-cho-hay-sai-nhat" aria-label="Permalink to &quot;Bước 1. Tải đúng file — đây là chỗ hay sai nhất&quot;">​</a></h3><ol><li>Vào <code>codeblocks.org/downloads/binaries</code>, chọn Windows.</li><li>Trong danh sách file, lấy dòng có chữ <strong>mingw</strong> trong tên, dạng <code>codeblocks-XX.XXmingw-setup.exe</code>.</li><li>Bản <code>codeblocks-XX.XX-setup.exe</code> (không có chữ mingw) <strong>không kèm bộ biên dịch</strong> — cài xong mở được nhưng bấm Build sẽ báo không tìm thấy compiler.</li></ol><h3 id="buoc-2-cai-va-chon-compiler" tabindex="-1">Bước 2. Cài và chọn compiler <a class="header-anchor" href="#buoc-2-cai-va-chon-compiler" aria-label="Permalink to &quot;Bước 2. Cài và chọn compiler&quot;">​</a></h3><ol><li>Bấm Next liên tục, giữ mặc định.</li><li>Lần đầu mở, nó hiện bảng “Compilers auto-detection”. Chọn <strong>GNU GCC Compiler</strong> rồi bấm <strong>Set as default</strong> → OK.</li></ol><h3 id="buoc-3-tao-project-va-them-file" tabindex="-1">Bước 3. Tạo project và thêm file <a class="header-anchor" href="#buoc-3-tao-project-va-them-file" aria-label="Permalink to &quot;Bước 3. Tạo project và thêm file&quot;">​</a></h3><ol><li><code>File → New → Project… → Console application → Next → C++ → Next</code></li><li>Đặt tên project và chọn thư mục lưu → Next → Finish.</li><li>Thêm file: <code>File → New → Empty file</code> → nó hỏi thêm vào project → <strong>Yes</strong> → lưu với đúng tên, ví dụ <code>Document.h</code>.</li><li>Hoặc nếu file đã có sẵn trên đĩa: <code>Project → Add files…</code> rồi chọn.</li></ol><h3 id="buoc-4-dich-va-chay" tabindex="-1">Bước 4. Dịch và chạy <a class="header-anchor" href="#buoc-4-dich-va-chay" aria-label="Permalink to &quot;Bước 4. Dịch và chạy&quot;">​</a></h3><ol><li><code>Build → Build and run</code> hoặc bấm <strong>F9</strong>.</li><li>Khung <strong>Build log</strong> phía dưới cho biết có lỗi hay không.</li></ol><h3 id="buoc-5-bat-c-17" tabindex="-1">Bước 5. Bật C++17 <a class="header-anchor" href="#buoc-5-bat-c-17" aria-label="Permalink to &quot;Bước 5. Bật C++17&quot;">​</a></h3><p>Một lần duy nhất: <code>Settings → Compiler… → Compiler settings → Compiler Flags</code>, tích ô <code>Have g++ follow the C++17 ISO standard [-std=c++17]</code>.</p><h2 id="e-3-visual-studio-community" tabindex="-1">E.3 Visual Studio Community <a class="header-anchor" href="#e-3-visual-studio-community" aria-label="Permalink to &quot;E.3 Visual Studio Community&quot;">​</a></h2><div class="hop chu-y"><p class="hop-tieu-de">Cân nhắc trước khi tải</p><p>Bộ này khoảng <strong>8 GB</strong> và cài mất 30–60 phút. Nếu mạng chậm hoặc ổ đĩa còn dưới 20 GB, dùng Dev-C++ ở <a href="./phu-luc-e.html#e-1-dev-c-khuyen-dung-cho-nguoi-moi">mục E.1</a> — môn này không cần gì mà Visual Studio có thêm.</p><p>Chú ý: <strong>Visual Studio</strong> và <strong>Visual Studio Code</strong> là hai phần mềm hoàn toàn khác nhau, cùng hãng. Mục này nói về Visual Studio.</p></div><figure class="hinh"><img src="'+r+'" alt="Hình E.5 — Visual Studio Installer. Phải tích ô “Desktop development with C++”." width="600" loading="lazy"><figcaption>Hình E.5 — Visual Studio Installer. Phải tích ô “Desktop development with C++”.</figcaption></figure><h3 id="buoc-1-tai-va-chon-đung-workload" tabindex="-1">Bước 1. Tải và chọn đúng workload <a class="header-anchor" href="#buoc-1-tai-va-chon-đung-workload" aria-label="Permalink to &quot;Bước 1. Tải và chọn đúng workload&quot;">​</a></h3><ol><li>Vào <code>visualstudio.microsoft.com/downloads</code>, tải <strong>Visual Studio Community</strong> (bản miễn phí).</li><li>Chạy file tải về. Nó mở <strong>Visual Studio Installer</strong>.</li><li>Ở tab <strong>Workloads</strong>, tích duy nhất ô <strong>Desktop development with C++</strong>.</li><li>Bấm <strong>Install</strong> rồi chờ. Không tích ô này thì cài xong vẫn không dịch được C++.</li></ol><h3 id="tao-project-va-them-file" tabindex="-1">Tạo project và thêm file <a class="header-anchor" href="#tao-project-va-them-file" aria-label="Permalink to &quot;Tạo project và thêm file&quot;">​</a></h3><figure class="hinh"><img src="'+g+'" alt="Hình E.6 — Solution Explorer: file .h vào Header Files, file .cpp vào Source Files." width="600" loading="lazy"><figcaption>Hình E.6 — Solution Explorer: file .h vào Header Files, file .cpp vào Source Files.</figcaption></figure><h3 id="buoc-2-tao-project" tabindex="-1">Bước 2. Tạo project <a class="header-anchor" href="#buoc-2-tao-project" aria-label="Permalink to &quot;Bước 2. Tạo project&quot;">​</a></h3><ol><li><code>Create a new project → Console App (C++)</code> → Next.</li><li>Đặt tên, chọn thư mục, bấm <strong>Create</strong>.</li><li>Nó tạo sẵn một file <code>.cpp</code> trùng tên project. Bạn có thể đổi tên nó thành <code>main.cpp</code> cho khớp đề.</li></ol><h3 id="buoc-3-them-file-h-va-cpp" tabindex="-1">Bước 3. Thêm file .h và .cpp <a class="header-anchor" href="#buoc-3-them-file-h-va-cpp" aria-label="Permalink to &quot;Bước 3. Thêm file .h và .cpp&quot;">​</a></h3><ol><li>Chuột phải vào <strong>Header Files</strong> ở Solution Explorer → <code>Add → New Item… → Header File (.h)</code> → đặt tên <code>Document.h</code> → Add.</li><li>Chuột phải vào <strong>Source Files</strong> → <code>Add → New Item… → C++ File (.cpp)</code> → đặt tên <code>Document.cpp</code> → Add.</li></ol><h3 id="buoc-4-dich-va-chay-1" tabindex="-1">Bước 4. Dịch và chạy <a class="header-anchor" href="#buoc-4-dich-va-chay-1" aria-label="Permalink to &quot;Bước 4. Dịch và chạy&quot;">​</a></h3><ol><li><code>Build → Build Solution</code> (<strong>Ctrl+Shift+B</strong>).</li><li><code>Debug → Start Without Debugging</code> (<strong>Ctrl+F5</strong>) — dùng cái này để cửa sổ không đóng ngay.</li></ol><div class="hop chu-y"><p class="hop-tieu-de">Hai điều riêng của Visual Studio</p><p><strong>1. Nó dùng compiler MSVC, không phải g++.</strong> Code của môn này chạy được ở cả hai, nhưng nếu bạn vô tình dùng một cú pháp riêng của MSVC thì máy người chấm có thể không dịch được. Cách phòng: chỉ viết những gì sách này dạy.</p><p><strong>2. Khi nộp bài, chỉ nộp các file </strong><code>.h</code><strong> và </strong><code>.cpp</code>. Không nộp thư mục <code>.vs</code>, file <code>.sln</code>, <code>.vcxproj</code> hay thư mục <code>x64</code> — chúng nặng và không cần thiết.</p></div><h2 id="e-4-clion" tabindex="-1">E.4 CLion <a class="header-anchor" href="#e-4-clion" aria-label="Permalink to &quot;E.4 CLion&quot;">​</a></h2><figure class="hinh"><img src="'+s+'" alt="Hình E.7 — CLion: mỗi file .cpp mới phải được khai vào CMakeLists.txt." width="600" loading="lazy"><figcaption>Hình E.7 — CLion: mỗi file .cpp mới phải được khai vào CMakeLists.txt.</figcaption></figure><h3 id="buoc-1-đang-ky-license-sinh-vien-va-cai" tabindex="-1">Bước 1. Đăng ký license sinh viên và cài <a class="header-anchor" href="#buoc-1-đang-ky-license-sinh-vien-va-cai" aria-label="Permalink to &quot;Bước 1. Đăng ký license sinh viên và cài&quot;">​</a></h3><ol><li>Vào <code>jetbrains.com/community/education</code>, đăng ký bằng email trường. Miễn phí.</li><li>Tải và cài CLion. Bấm Next liên tục.</li><li>Lần đầu mở, nếu nó hỏi toolchain: chọn <strong>Bundled MinGW</strong> — bộ biên dịch kèm sẵn, không cần cài thêm.</li></ol><h3 id="buoc-2-tao-project-1" tabindex="-1">Bước 2. Tạo project <a class="header-anchor" href="#buoc-2-tao-project-1" aria-label="Permalink to &quot;Bước 2. Tạo project&quot;">​</a></h3><ol><li><code>New Project → C++ Executable</code>, chọn C++ standard là <code>C++17</code>.</li><li>Đặt tên và chọn thư mục, bấm Create.</li></ol><h3 id="buoc-3-them-file-—-va-đung-quen-cmakelists-txt" tabindex="-1">Bước 3. Thêm file — và đừng quên CMakeLists.txt <a class="header-anchor" href="#buoc-3-them-file-—-va-đung-quen-cmakelists-txt" aria-label="Permalink to &quot;Bước 3. Thêm file — và đừng quên CMakeLists.txt&quot;">​</a></h3><ol><li>Chuột phải vào tên project → <code>New → C/C++ Header File</code> hoặc <code>C/C++ Source File</code>.</li><li>Mở file <code>CMakeLists.txt</code> và thêm tên file <code>.cpp</code> mới vào trong <code>add_executable(...)</code>.</li><li>Bấm <strong>Reload changes</strong> ở thanh thông báo hiện lên phía trên.</li></ol><div class="hop chu-y"><p class="hop-tieu-de">Lỗi số một của CLion</p><p>CLion không tự biết file mới cần được dịch — <code>CMakeLists.txt</code> mới là danh sách thật. Thêm file rồi quên khai vào đó thì bạn lại nhận <code>undefined reference</code> y như trường hợp Dev-C++.</p><p>Khi tạo file mới, CLion thường hỏi “Add to targets?” — bấm <strong>OK</strong> là nó tự khai giúp. Nếu bấm Cancel thì phải tự sửa tay.</p></div><h3 id="buoc-4-dich-va-chay-2" tabindex="-1">Bước 4. Dịch và chạy <a class="header-anchor" href="#buoc-4-dich-va-chay-2" aria-label="Permalink to &quot;Bước 4. Dịch và chạy&quot;">​</a></h3><p>Bấm nút tam giác xanh ở góc trên phải, hoặc <strong>Shift+F10</strong>.</p><h2 id="e-5-vs-code-chi-muc-nay-moi-can-cai-g" tabindex="-1">E.5 VS Code (chỉ mục này mới cần cài g++) <a class="header-anchor" href="#e-5-vs-code-chi-muc-nay-moi-can-cai-g" aria-label="Permalink to &quot;E.5 VS Code (chỉ mục này mới cần cài g++)&quot;">​</a></h2><div class="hop chu-y"><p class="hop-tieu-de">VS Code không phải IDE</p><p>Nó là một trình soạn thảo — rất tốt để gõ chữ, nhưng bên trong <strong>không có bộ biên dịch</strong>. Bấm nút Run trong VS Code khi chưa cài compiler thì không có gì xảy ra, hoặc nó báo không tìm thấy <code>g++</code>.</p><p>Vì vậy mục này có nhiều bước hơn bốn mục trên. Nếu bạn chưa dùng VS Code cho môn nào khác, cân nhắc chọn Dev-C++ ở <a href="./phu-luc-e.html#e-1-dev-c-khuyen-dung-cho-nguoi-moi">mục E.1</a> để đỡ mất thời gian.</p></div><figure class="hinh"><img src="'+p+'" alt="Hình E.8 — VS Code: gõ code bên phải, biên dịch bằng lệnh trong cửa sổ Terminal phía dưới." width="600" loading="lazy"><figcaption>Hình E.8 — VS Code: gõ code bên phải, biên dịch bằng lệnh trong cửa sổ Terminal phía dưới.</figcaption></figure><figure class="hinh"><img src="'+u+'" alt="Ảnh thật E.8a — VS Code chạy trên Windows với đúng project ở mục 1.2: Explorer bên trái có Document.h, Document.cpp, main.cpp; Terminal phía dưới đã chạy lệnh g++ và in ra kết quả. Sau khi dịch, file main.exe xuất hiện trong Explorer. Giáo trình tự chụp." width="600" loading="lazy"><figcaption>Ảnh thật E.8a — VS Code chạy trên Windows với đúng project ở mục 1.2: Explorer bên trái có Document.h, Document.cpp, main.cpp; Terminal phía dưới đã chạy lệnh g++ và in ra kết quả. Sau khi dịch, file main.exe xuất hiện trong Explorer. Giáo trình tự chụp.</figcaption></figure><h3 id="buoc-1-cai-vs-code-va-extension-c-c" tabindex="-1">Bước 1. Cài VS Code và extension C/C++ <a class="header-anchor" href="#buoc-1-cai-vs-code-va-extension-c-c" aria-label="Permalink to &quot;Bước 1. Cài VS Code và extension C/C++&quot;">​</a></h3><ol><li>Tải ở <code>code.visualstudio.com</code>, cài bình thường.</li><li>Mở VS Code, bấm biểu tượng Extensions ở cột trái (hoặc <strong>Ctrl+Shift+X</strong>).</li><li>Tìm <code>C/C++</code> của <strong>Microsoft</strong>, bấm Install. Cái này cho tô màu và gợi ý — nó <strong>không</strong> phải bộ biên dịch.</li></ol><h3 id="buoc-2-cai-bo-bien-dich-mingw-w64-qua-msys2" tabindex="-1">Bước 2. Cài bộ biên dịch MinGW-w64 qua MSYS2 <a class="header-anchor" href="#buoc-2-cai-bo-bien-dich-mingw-w64-qua-msys2" aria-label="Permalink to &quot;Bước 2. Cài bộ biên dịch MinGW-w64 qua MSYS2&quot;">​</a></h3><ol><li>Vào <code>msys2.org</code>, tải file cài đặt dạng <code>msys2-x86_64-*.exe</code>.</li><li>Chạy nó, bấm Next liên tục. Giữ nguyên thư mục mặc định <code>C:\\msys64</code> — các bước sau giả định đường dẫn này.</li><li>Cài xong, một cửa sổ đen MSYS2 tự mở. Gõ đúng dòng này rồi Enter:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pacman -S mingw-w64-ucrt-x86_64-gcc</span></span></code></pre></div><ol start="4"><li>Nó hỏi <code>Proceed with installation? [Y/n]</code> → gõ <code>Y</code> rồi Enter. Chờ vài phút rồi đóng cửa sổ đen.</li></ol><h3 id="buoc-3-them-compiler-vao-path" tabindex="-1">Bước 3. Thêm compiler vào PATH <a class="header-anchor" href="#buoc-3-them-compiler-vao-path" aria-label="Permalink to &quot;Bước 3. Thêm compiler vào PATH&quot;">​</a></h3><p>Đây là bước để Windows biết <code>g++</code> nằm ở đâu. Làm đúng bốn bước trong hình.</p><figure class="hinh"><img src="'+m+`" alt="Hình E.9 — Bốn bước thêm C:\\msys64\\ucrt64\\bin vào biến môi trường PATH." width="600" loading="lazy"><figcaption>Hình E.9 — Bốn bước thêm C:\\msys64\\ucrt64\\bin vào biến môi trường PATH.</figcaption></figure><ol><li>Bấm phím Windows, gõ <code>environment</code>, chọn “Edit the system environment variables”.</li><li>Bấm nút <strong>Environment Variables…</strong> ở góc dưới.</li><li>Ở khung <strong>System variables</strong>, chọn dòng <code>Path</code> rồi bấm <strong>Edit…</strong>.</li><li>Bấm <strong>New</strong>, dán vào <code>C:\\msys64\\ucrt64\\bin</code>, rồi bấm OK ba lần để đóng hết.</li></ol><h3 id="buoc-4-kiem-tra" tabindex="-1">Bước 4. Kiểm tra <a class="header-anchor" href="#buoc-4-kiem-tra" aria-label="Permalink to &quot;Bước 4. Kiểm tra&quot;">​</a></h3><p>Mở <strong>một cửa sổ dòng lệnh mới</strong> (cửa sổ cũ không biết thay đổi vừa rồi) và gõ:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><div class="ket-qua thay"><p class="ket-qua-nhan">Đúng thì bạn sẽ thấy (số phiên bản có thể khác):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g++.exe (Rev8, Built by MSYS2 project) 15.2.0</span></span>
<span class="line"><span>Copyright (C) 2025 Free Software Foundation, Inc.</span></span></code></pre></div></div><div class="ket-qua loi"><p class="ket-qua-nhan">Nếu vẫn hiện:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;g++&#39; is not recognized as an internal or external command,</span></span>
<span class="line"><span>operable program or batch file.</span></span></code></pre></div></div><p>→ Kiểm tra lại ba điều: (a) thư mục <code>C:\\msys64\\ucrt64\\bin</code> có tồn tại và có file <code>g++.exe</code> trong đó không; (b) bạn đã dán đúng đường dẫn đó vào PATH chưa; (c) bạn đã <strong>đóng và mở lại</strong> cửa sổ dòng lệnh chưa.</p><h3 id="buoc-5-lam-viec-trong-vs-code" tabindex="-1">Bước 5. Làm việc trong VS Code <a class="header-anchor" href="#buoc-5-lam-viec-trong-vs-code" aria-label="Permalink to &quot;Bước 5. Làm việc trong VS Code&quot;">​</a></h3><ol><li><code>File → Open Folder…</code> rồi chọn thư mục bài làm. <strong>Mở thư mục, đừng mở từng file</strong> — có mở thư mục thì mới thấy được cả dự án.</li><li>Gõ code. Tạo file mới bằng biểu tượng “New File” ở khung Explorer bên trái, nhớ gõ cả đuôi <code>.h</code> hay <code>.cpp</code>.</li><li><code>Terminal → New Terminal</code> để mở cửa sổ lệnh ngay trong VS Code, rồi gõ:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++17</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.exe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./main.exe</span></span></code></pre></div><div class="hop chu-y"><p class="hop-tieu-de">Đừng dùng nút Run của VS Code cho dự án nhiều file</p><p>Nút tam giác “Run C/C++ File” chỉ dịch <strong>file đang mở</strong>. Với dự án 10 file, nó sẽ báo <code>undefined reference</code> cho mọi hàm nằm ở file khác.</p><p>Dùng lệnh <code>g++ ... *.cpp</code> trong Terminal — đó cũng đúng là lệnh người chấm sẽ dùng.</p></div><h2 id="e-6-bat-ke-dung-cong-cu-nao" tabindex="-1">E.6 Bất kể dùng công cụ nào <a class="header-anchor" href="#e-6-bat-ke-dung-cong-cu-nao" aria-label="Permalink to &quot;E.6 Bất kể dùng công cụ nào&quot;">​</a></h2><p>Ba việc dưới đây không phụ thuộc công cụ, và cả ba đều có trong thang điểm:</p><h3 id="_1-ten-file-phai-đung-tung-chu" tabindex="-1">1. Tên file phải đúng từng chữ <a class="header-anchor" href="#_1-ten-file-phai-đung-tung-chu" aria-label="Permalink to &quot;1. Tên file phải đúng từng chữ&quot;">​</a></h3><p>Đề ghi <code>Document.h</code> thì phải là <code>Document.h</code> — không phải <code>document.h</code>, không phải <code>Document .h</code>, và không phải <code>Document.h.txt</code> (lỗi này xảy ra khi lưu bằng Notepad mà không chọn “All files”).</p><h3 id="_2-nop-đung-cau-truc" tabindex="-1">2. Nộp đúng cấu trúc <a class="header-anchor" href="#_2-nop-đung-cau-truc" aria-label="Permalink to &quot;2. Nộp đúng cấu trúc&quot;">​</a></h3><figure class="hinh"><img src="`+b+'" alt="Hình E.10 — Thư mục bài làm chỉ gồm file .h và .cpp, nén thành .zip đặt tên theo MSSV." width="600" loading="lazy"><figcaption>Hình E.10 — Thư mục bài làm chỉ gồm file .h và .cpp, nén thành .zip đặt tên theo MSSV.</figcaption></figure><ul><li>Thư mục tên <code>&lt;MSSV&gt;_wNN</code>, ví dụ <code>23130007_w05</code>.</li><li>Bên trong chỉ có các file <code>.h</code> và <code>.cpp</code> (cộng ảnh UML nếu đề yêu cầu).</li><li>Xoá <code>main.exe</code>, thư mục <code>.vscode</code>, <code>.vs</code>, <code>build</code>, <code>cmake-build-debug</code>, <code>x64</code> — chúng chỉ làm file nén phình ra.</li><li>Nén thành <code>.zip</code>, <strong>không phải </strong><code>.rar</code>. Tên: <code>&lt;MSSV&gt;_&lt;Ho ten khong dau&gt;.zip</code>.</li></ul><h3 id="_3-kiem-tra-lan-cuoi-truoc-khi-nop" tabindex="-1">3. Kiểm tra lần cuối trước khi nộp <a class="header-anchor" href="#_3-kiem-tra-lan-cuoi-truoc-khi-nop" aria-label="Permalink to &quot;3. Kiểm tra lần cuối trước khi nộp&quot;">​</a></h3><div class="hop ghi-chu"><p class="hop-tieu-de">Một phút này đáng 5 điểm</p><p>Nếu công cụ của bạn là Dev-C++, Code::Blocks hay CLion (đều dùng GCC bên trong): mở cửa sổ dòng lệnh, vào thư mục bài làm, gõ đúng lệnh người chấm sẽ gõ:</p><p><code>g++ -std=c++17 -Wall *.cpp -o main.exe</code></p><p>Nếu máy chưa có <code>g++</code> trong PATH thì ít nhất hãy làm <strong>Rebuild toàn bộ project</strong> một lần (không phải Build thường) và xác nhận 0 error — Rebuild buộc dịch lại tất cả file, còn Build chỉ dịch file vừa sửa.</p><p>Với Visual Studio: <code>Build → Rebuild Solution</code> rồi xác nhận 0 error.</p></div><div class="hop chu-y"><p class="hop-tieu-de">Muốn thay hình vẽ bằng ảnh chụp thật?</p><p>Các hình trong phụ lục này là hình vẽ minh họa. Nếu thầy/cô hoặc sinh viên chụp được ảnh màn hình thật của từng bước, chỉ cần ghi đè file <code>.png</code> cùng tên trong thư mục <code>giaotrinh/hinh/</code> rồi dựng lại file <code>.docx</code> — sách tự lấy ảnh mới, không phải sửa gì khác.</p><p>Tên file tương ứng: <code>E0_chon_cong_cu</code>, <code>E1_devcpp_tai</code>, <code>E1_devcpp_project</code>, <code>E2_codeblocks</code>, <code>E3_vs_installer</code>, <code>E3_vs_solution</code>, <code>E4_clion</code>, <code>E5_vscode</code>, <code>E6_path</code>, <code>E7_thu_muc</code>.</p></div><h2 id="e-7-trinh-bien-dich-online-khi-may-chua-cai-gi" tabindex="-1">E.7 Trình biên dịch online (khi máy chưa cài gì) <a class="header-anchor" href="#e-7-trinh-bien-dich-online-khi-may-chua-cai-gi" aria-label="Permalink to &quot;E.7 Trình biên dịch online (khi máy chưa cài gì)&quot;">​</a></h2><p>Chưa kịp cài, máy hỏng, hay đang dùng máy mượn thì vẫn làm bài ở lớp được bằng một trình biên dịch chạy trên trình duyệt. Giáo trình dùng <strong>OnlineGDB</strong>: không cần tài khoản, dịch được dự án nhiều file <code>.h</code> / <code>.cpp</code>, và bên trong là g++ thật.</p><div class="hop chu-y"><p class="hop-tieu-de">Chỉ dùng tạm</p><p>Bài chấm điểm tuần 8 và phòng thi thực hành <strong>không có mạng</strong>. Trước tuần 8 phải cài xong một công cụ ở <a href="./phu-luc-e.html#e-1-dev-c-khuyen-dung-cho-nguoi-moi">mục E.1</a> – E.5 và dịch thử được trên chính máy mình.</p><p>Trang có quảng cáo. Đừng bấm vào quảng cáo; không cần đăng nhập hay cài thêm gì theo lời mời trên trang.</p></div><h3 id="buoc-1-mo-trang-va-thiet-lap-mot-lan" tabindex="-1">Bước 1. Mở trang và thiết lập một lần <a class="header-anchor" href="#buoc-1-mo-trang-va-thiet-lap-mot-lan" aria-label="Permalink to &quot;Bước 1. Mở trang và thiết lập một lần&quot;">​</a></h3><ol><li>Vào <code>onlinegdb.com/online_c++_compiler</code>.</li><li>Góc trên bên phải, ô <strong>Language</strong> chọn <code>C++ 17</code>.</li><li>Bấm nút bánh răng ngay cạnh ô đó → <strong>Extra Compiler Flags</strong> → gõ <code>-Wall</code> → <strong>Ok</strong> → <strong>Done</strong>. Từ giờ g++ báo cả cảnh báo, giống lệnh <code>g++ -std=c++17 -Wall</code> trong sách.</li></ol><p>Trình duyệt tự nhớ hai thiết lập này cho lần sau. Đổi máy hay đổi trình duyệt thì làm lại.</p><h3 id="buoc-2-them-file-h-va-cpp" tabindex="-1">Bước 2. Thêm file .h và .cpp <a class="header-anchor" href="#buoc-2-them-file-h-va-cpp" aria-label="Permalink to &quot;Bước 2. Thêm file .h và .cpp&quot;">​</a></h3><ol><li>Trang mở sẵn một file <code>main.cpp</code> có code mẫu. Xoá hết code mẫu rồi gõ code của bạn.</li><li>Bấm nút <strong>New File</strong> (biểu tượng tờ giấy, ngoài cùng bên trái thanh công cụ, hoặc <code>Ctrl+M</code>), gõ đúng tên, ví dụ <code>Document.h</code>, bấm <strong>ok</strong>. File mới hiện thành một thẻ cạnh <code>main.cpp</code>.</li><li>Đặt sai tên thì bấm dấu <strong>⋮</strong> trên thẻ file → <strong>Rename</strong>. OnlineGDB phân biệt chữ hoa với chữ thường: <code>document.h</code> không phải <code>Document.h</code>.</li></ol><h3 id="buoc-3-dich-va-chay" tabindex="-1">Bước 3. Dịch và chạy <a class="header-anchor" href="#buoc-3-dich-va-chay" aria-label="Permalink to &quot;Bước 3. Dịch và chạy&quot;">​</a></h3><ol><li>Bấm <strong>Run</strong> (hoặc <code>F9</code>). OnlineGDB tự dịch <strong>mọi</strong> file <code>.cpp</code> trong dự án, đúng như lệnh <code>g++ *.cpp</code>.</li><li>Kết quả hiện ở khung phía dưới. Cảnh báo, nếu có, nằm ngay đầu khung, phía trên các dòng chương trình in ra.</li><li>Dịch hỏng thì khung dưới chỉ ghi <code>Compilation failed due to following error(s).</code> Bấm thẻ <strong>stderr</strong> để đọc lỗi.</li><li>Chương trình có <code>cin</code>: gõ dữ liệu ngay vào khung kết quả khi chương trình chờ nhập, rồi Enter.</li><li>Bài cần đọc file văn bản, ví dụ <code>playlist.txt</code>: tạo file đó bằng New File như trên rồi gõ nội dung vào. Chương trình mở được nó bằng đúng tên đó.</li></ol><h3 id="buoc-4-cat-bai-truoc-khi-đong-tab" tabindex="-1">Bước 4. Cất bài trước khi đóng tab <a class="header-anchor" href="#buoc-4-cat-bai-truoc-khi-đong-tab" aria-label="Permalink to &quot;Bước 4. Cất bài trước khi đóng tab&quot;">​</a></h3><p>Không đăng nhập thì OnlineGDB <strong>không lưu</strong> code: tải lại trang là chỉ còn <code>main.cpp</code> mẫu. Trước khi đóng, bấm mũi tên cạnh nút tải về trên thanh công cụ → <strong>Download all files</strong>. Muốn làm tiếp ở buổi sau, dùng nút <strong>Upload File</strong> (biểu tượng đám mây) để đưa từng file lên lại.</p><div class="hop ghi-chu"><p class="hop-tieu-de">Khác gì so với g++ trên máy</p><p>OnlineGDB chạy g++ 14 trên Linux. Nội dung thông báo lỗi giống trong sách, chỉ khác vài chỗ: dấu nháy là <code>‘ ’</code> thay cho <code>&#39; &#39;</code>; đường dẫn thư viện có dạng <code>/nix/store/.../include/c++/14.3.0/...</code> thay cho <code>C:/msys64/...</code>; và không có file <code>main.exe</code> nào để chép về.</p><p>Cách đọc lỗi ở <a href="./phu-luc-a.html">Phụ lục A</a> dùng được y nguyên: bỏ qua dòng có đường dẫn chứa <code>include/c++</code>, tìm dòng mang tên file của bạn.</p></div><p>Dự phòng khi không vào được OnlineGDB: <code>programiz.com/cpp-programming/online-compiler</code>. Trang này chỉ có <strong>một</strong> file <code>main.cpp</code>: đủ cho bài chưa chia file, không làm được bài nhiều file.</p><h2 id="nguon-anh" tabindex="-1">Nguồn ảnh <a class="header-anchor" href="#nguon-anh" aria-label="Permalink to &quot;Nguồn ảnh&quot;">​</a></h2><p>Hai ảnh chụp thật trong phụ lục này, dùng nguyên bản không chỉnh sửa:</p><table tabindex="0"><thead><tr><th>Ảnh</th><th>Tác giả</th><th>Giấy phép</th><th>Nguồn</th></tr></thead><tbody><tr><td>E.3a — Dev-C++ 4.9.9.2</td><td>Francesco Betti Sorbelli</td><td>GNU GPL v2 trở lên</td><td><code>commons.wikimedia.org/wiki/File:Devcpp4.png</code></td></tr><tr><td>E.8a — VS Code 1.136</td><td>Giáo trình tự chụp</td><td>Thuộc giáo trình</td><td>Chụp trên Windows 11, 13/09/2026, với project <a href="./chuong-1.html#_1-2-chuong-trinh-đau-tien-—-tung-buoc-tu-thu-muc-trong">mục 1.2</a></td></tr></tbody></table><p>Mọi hình còn lại (E.1, E.2, E.3…) là hình vẽ minh họa do giáo trình tự thực hiện.</p><p>Hướng dẫn chính thức có ảnh chụp từng bước, để đọc thêm: VS Code + MinGW tại <code>code.visualstudio.com/docs/cpp/config-mingw</code>.</p>',119)])])}const _=c(v,[["render",k]]);export{E as __pageData,_ as default};
